nginx_nginx-rutas.conf.contenido:
# Incluir dentro del server 8595, antes del location / existente.
location = /api/v1/presidencia {
    include /etc/nginx/sivas-presidencia-proxy.conf;
}
location ^~ /api/v1/presidencia/ {
    include /etc/nginx/sivas-presidencia-proxy.conf;
}
location ^~ /vista/ {
    include /etc/nginx/sivas-presidencia-proxy.conf;
}
location = /presidencia-api/docs {
    include /etc/nginx/sivas-presidencia-proxy.conf;
}
location = /presidencia-api/openapi.json {
    include /etc/nginx/sivas-presidencia-proxy.conf;
}
location ~ ^/presidencia-api/health/(live|ready|shiny)$ {
    rewrite ^/presidencia-api/(.*)$ /$1 break;
    include /etc/nginx/sivas-presidencia-proxy.conf;
}

nginx_nginx-proxy.conf.contenido:
# Incluir únicamente en los location de la integración.
proxy_pass http://127.0.0.1:8000;
proxy_http_version 1.1;
proxy_set_header Host $host;
proxy_set_header X-Forwarded-Proto https;
proxy_set_header X-Forwarded-For $remote_addr;
proxy_set_header Upgrade $http_upgrade;
proxy_set_header Connection $connection_upgrade_analytics_msp;
proxy_read_timeout 3600s;
proxy_send_timeout 3600s;
proxy_buffering off;
proxy_redirect off;
# No registrar capacidades temporales de /vista/ ni claves de solicitudes.
access_log off;
error_log /var/log/nginx/sivas-presidencia-error.log crit;
# Declarar headers aquí impide heredar X-Frame-Options SAMEORIGIN del sitio.
# La API agrega su propia lista explícita CSP frame-ancestors.
add_header X-Content-Type-Options nosniff always;
add_header Referrer-Policy no-referrer always;
add_header X-Robots-Tag "noindex, nofollow, noarchive" always;
